"""
版本匹配器（自 services.version_matcher 迁移）

Minecraft 版本匹配、加载器版本匹配、版本范围处理。
依赖可选 CatalogPort（需统一加载器版本时传入）。
"""

from dataclasses import dataclass
from functools import lru_cache
from typing import List, Optional, Union

from loguru import logger

from modfetch.domain.config_models import ConditionalEntry, ModLoader
from modfetch.ports.catalog import CatalogPort


# ---------------------------------------------------------------------------
# cond 表达式（风格 A：紧凑前缀运算符）
#
# 语法: 布尔表达式, 支持 &&（AND）/ ||（OR）/ !（NOT）/ 括号分组
#   - 字面量类型前缀（大小写不敏感）:
#       v:1.21.1  /  version:1.21.1   MC 版本（精确匹配）
#       l:fabric  /  loader:fabric     加载器（大小写不敏感）
#       f:shaders /  feature:shaders   feature 标签（须在启用列表内）
#   - 无前缀字面量: 按 版本 → 加载器 → feature 顺序自动推断
#   - 优先级: !  >  &&  >  ||，括号覆盖
#   - 字符串或字符串列表（列表元素隐含 AND）
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class _CondLiteral:
    """cond 表达式字面量节点；kind: version / loader / feature / auto"""

    kind: str
    value: str


@dataclass(frozen=True)
class _CondNot:
    operand: object


@dataclass(frozen=True)
class _CondAnd:
    left: object
    right: object


@dataclass(frozen=True)
class _CondOr:
    left: object
    right: object


class CondExpr:
    """cond 条件表达式解析与求值（配置语法错误 fail-fast）"""

    _PREFIXES = (
        ("version:", "version"),
        ("loader:", "loader"),
        ("feature:", "feature"),
        ("v:", "version"),
        ("l:", "loader"),
        ("f:", "feature"),
    )

    @staticmethod
    def evaluate(
        cond: Union[str, List[str]],
        version: str,
        features: List[str],
        loader: Optional[str] = None,
    ) -> bool:
        """按当前 (version, loader, features) 上下文求值 cond 表达式

        cond 为字符串时直接求值；为列表时各元素须全部为真（AND）。
        空字符串 / 空列表返回 False（调用方据此回退到单独字段）。
        """
        conds = [cond] if isinstance(cond, str) else list(cond)
        if not conds or all(not c.strip() for c in conds):
            return False
        for c in conds:
            if not CondExpr._eval_tree(CondExpr._compile(c), version, features, loader):
                return False
        return True

    # -- 编译（tokenize + 递归下降，带缓存） --------------------------------

    @staticmethod
    @lru_cache(maxsize=256)
    def _compile(expr: str) -> object:
        """把表达式字符串编译为 AST；语法错误抛 ValueError（中文消息）"""
        tokens = CondExpr._tokenize(expr)
        pos = [0]

        def peek() -> Optional[tuple]:
            return tokens[pos[0]] if pos[0] < len(tokens) else None

        def advance() -> Optional[tuple]:
            token = peek()
            pos[0] += 1
            return token

        def parse_or() -> object:
            node = parse_and()
            while peek() is not None and peek()[0] == "OR":
                advance()
                node = _CondOr(node, parse_and())
            return node

        def parse_and() -> object:
            node = parse_unary()
            while peek() is not None and peek()[0] == "AND":
                advance()
                node = _CondAnd(node, parse_unary())
            return node

        def parse_unary() -> object:
            if peek() is not None and peek()[0] == "NOT":
                advance()
                return _CondNot(parse_unary())
            return parse_primary()

        def parse_primary() -> object:
            token = advance()
            if token is None:
                raise ValueError(f"cond 表达式语法错误: {expr!r}（表达式不完整）")
            kind, value = token
            if kind == "LPAREN":
                node = parse_or()
                if peek() is None or advance()[0] != "RPAREN":
                    raise ValueError(
                        f"cond 表达式语法错误: {expr!r}（缺少右括号）"
                    )
                return node
            if kind == "LITERAL":
                return CondExpr._classify(value)
            raise ValueError(
                f"cond 表达式语法错误: {expr!r}（{value} 位置意外）"
            )

        try:
            node = parse_or()
        except ValueError:
            raise
        except Exception as e:  # 防御: 解析内部意外错误统一转为配置错误
            raise ValueError(f"cond 表达式解析失败: {expr!r}: {e}") from e
        if pos[0] != len(tokens):
            raise ValueError(
                f"cond 表达式语法错误: {expr!r}（存在多余内容: "
                f"{tokens[pos[0]][1]!r}）"
            )
        return node

    @staticmethod
    def _tokenize(expr: str) -> List[tuple]:
        """把表达式切分为 (类型, 值) 序列; 非法运算符字符直接报错"""
        tokens: List[tuple] = []
        i = 0
        n = len(expr)
        while i < n:
            ch = expr[i]
            if ch.isspace():
                i += 1
            elif ch == "(":
                tokens.append(("LPAREN", "("))
                i += 1
            elif ch == ")":
                tokens.append(("RPAREN", ")"))
                i += 1
            elif ch == "&":
                if expr[i : i + 2] != "&&":
                    raise ValueError(
                        f"cond 表达式语法错误: {expr!r}（{i} 处 '&' 必须成对 "
                        f"写成 &&）"
                    )
                tokens.append(("AND", "&&"))
                i += 2
            elif ch == "|":
                if expr[i : i + 2] != "||":
                    raise ValueError(
                        f"cond 表达式语法错误: {expr!r}（{i} 处 '|' 必须成对 "
                        f"写成 ||）"
                    )
                tokens.append(("OR", "||"))
                i += 2
            elif ch == "!":
                tokens.append(("NOT", "!"))
                i += 1
            else:
                # 字面量: 累积到空白 / 括号 / 运算符为止
                start = i
                while (
                    i < n
                    and not expr[i].isspace()
                    and expr[i] not in "()&|!"
                ):
                    i += 1
                if i == start:
                    raise ValueError(
                        f"cond 表达式语法错误: {expr!r}（{i} 处无法识别的字符 "
                        f"{expr[i]!r}）"
                    )
                tokens.append(("LITERAL", expr[start:i]))
        return tokens

    @staticmethod
    def _classify(literal: str) -> _CondLiteral:
        """按前缀分类字面量; 无前缀时标记 auto 由求值阶段按上下文推断"""
        lowered = literal.lower()
        for prefix, kind in CondExpr._PREFIXES:
            if lowered.startswith(prefix):
                return _CondLiteral(kind, literal[len(prefix) :])
        return _CondLiteral("auto", literal)

    # -- 求值 --------------------------------------------------------------

    @staticmethod
    def _eval_tree(
        node: object,
        version: str,
        features: List[str],
        loader: Optional[str],
    ) -> bool:
        if isinstance(node, _CondLiteral):
            return CondExpr._eval_literal(node, version, features, loader)
        if isinstance(node, _CondNot):
            return not CondExpr._eval_tree(node.operand, version, features, loader)
        if isinstance(node, _CondAnd):
            return CondExpr._eval_tree(
                node.left, version, features, loader
            ) and CondExpr._eval_tree(node.right, version, features, loader)
        if isinstance(node, _CondOr):
            return CondExpr._eval_tree(
                node.left, version, features, loader
            ) or CondExpr._eval_tree(node.right, version, features, loader)
        # 理论上不可达（编译阶段已限定 AST 节点类型）
        raise ValueError(f"未知的 cond 表达式节点: {node!r}")

    @staticmethod
    def _eval_literal(
        literal: _CondLiteral,
        version: str,
        features: List[str],
        loader: Optional[str],
    ) -> bool:
        kind, value = literal.kind, literal.value
        if kind == "version":
            return version == value
        if kind == "loader":
            # 无加载器上下文时保守排除（与 only_loader 语义一致）
            return loader is not None and loader.lower() == value.lower()
        if kind == "feature":
            return value in features
        # auto: 版本 → 加载器 → feature 顺序推断
        if version == value:
            return True
        if loader is not None and loader.lower() == value.lower():
            return True
        return value in features


class VersionMatcher:
    """版本匹配器

    负责 Minecraft 版本匹配、配置条目过滤（only_version/feature）
    与加载器版本查询，供计划生成阶段筛选条目。
    """

    def __init__(self, catalog: Optional[CatalogPort] = None):
        self.catalog = catalog

    def matches(
        self,
        version: str,
        target_versions: Union[str, List[str]],
    ) -> bool:
        """检查版本是否匹配目标版本列表（支持单字符串或列表）

        当前为精确匹配：version 必须逐字命中 target_versions。
        """
        if isinstance(target_versions, str):
            target_versions = [target_versions]
        return version in target_versions

    def should_include(
        self,
        entry: Union[ConditionalEntry, dict, str],
        version: str,
        features: List[str],
        loader: Optional[str] = None,
    ) -> bool:
        """判断项目是否应包含在当前构建中

        支持 ConditionalEntry(ModEntry/ExtraUrl) 对象、dict 与字符串条目：
        - cond: 表达式形式条件（优先级最高；声明后仅按表达式求值，
          only_version/only_loader/feature 全部忽略）
        - only_version: 版本命中指定列表才包含
        - only_loader: 加载器命中指定列表才包含（列表命中其一即可）；
          条目声明了 only_loader 但未提供 loader 上下文（None）时排除，
          避免无上下文时误包含
        - feature: 启用条件——条目声明的 feature 全部被启用才包含；
          未声明 feature 的条目始终包含（与 ConditionalEntry 文档一致）

        注: 历史实现对 dict 条目采用"全部启用则排除"的反向语义，
        且对象条目(dataclass)从未命中 dict 分支导致过滤失效；本方法
        统一为启用条件语义并支持对象条目。
        """
        # 对象条目（ModEntry/ExtraUrl）与 dict 均提取条件字段；字符串无条件
        if isinstance(entry, ConditionalEntry):
            cond = entry.cond
            only_version = entry.only_version
            only_loader = entry.only_loader
            cfg_features = entry.feature
        elif isinstance(entry, dict):
            cond = entry.get("cond")
            only_version = entry.get("only_version")
            only_loader = entry.get("only_loader")
            cfg_features = entry.get("feature")
        else:
            return True

        # cond 声明时优先于单独字段
        if cond:
            return CondExpr.evaluate(cond, version, features, loader)

        # only_version: 版本不在指定列表 → 排除
        if only_version:
            versions = (
                [only_version]
                if isinstance(only_version, str)
                else list(only_version)
            )
            if version not in versions:
                logger.debug(
                    f"[过滤] 排除 {entry}: only_version={versions} 不含 {version}"
                )
                return False

        # only_loader: 加载器不匹配 → 排除；无 loader 上下文时保守排除
        if only_loader:
            loaders = (
                [only_loader]
                if isinstance(only_loader, str)
                else list(only_loader)
            )
            normalized = [loader_val.lower() for loader_val in loaders]
            if loader is None or loader.lower() not in normalized:
                logger.debug(
                    f"[过滤] 排除 {entry}: only_loader={normalized} 不含 {loader}"
                )
                return False

        # feature: 启用条件——所有声明的功能标签都被启用才包含
        if cfg_features:
            feats = (
                [cfg_features]
                if isinstance(cfg_features, str)
                else list(cfg_features)
            )
            if not all(feature in features for feature in feats):
                logger.debug(
                    f"[过滤] 排除 {entry}: feature={feats} 未全部启用"
                )
                return False

        return True

    async def get_loader_version(
        self,
        loader: ModLoader,
        mc_version: str,
    ) -> Optional[str]:
        """获取模组加载器版本（统一走 CatalogPort）

        未注入 catalog 时返回 None，由调用方决定是否可选降级。
        """
        if not self.catalog:
            return None
        return await self.catalog.get_loader_version(loader.value, mc_version)